def test_order_history_unknown_customer(shop):
    response = shop.insights.handle_order_history("nobody")
    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_customer_with_no_orders(shop):
    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_includes_all_orders_newest_first(shop):
    ord1 = shop.orders.handle_create({
        "customer_id": "c1",
        "items": [{"sku": "BOOK", "quantity": 1}]
    }).body["order_id"]
    ord2 = shop.orders.handle_create({
        "customer_id": "c1",
        "items": [{"sku": "PEN", "quantity": 2}]
    }).body["order_id"]
    ord3 = shop.orders.handle_create({
        "customer_id": "c1",
        "items": [{"sku": "LAMP", "quantity": 1}]
    }).body["order_id"]

    response = shop.insights.handle_order_history("c1")
    assert response.status == 200
    orders = response.body["orders"]
    assert len(orders) == 3
    assert [o["order_id"] for o in orders] == [ord3, ord2, ord1]


def test_order_history_includes_total_cents_with_discount(shop):
    ord_id = shop.orders.handle_create({
        "customer_id": "c2",
        "items": [{"sku": "LAMP", "quantity": 2}]
    }).body["order_id"]

    response = shop.insights.handle_order_history("c2")
    orders = response.body["orders"]
    assert len(orders) == 1
    order = orders[0]
    assert order["order_id"] == ord_id
    assert order["total_cents"] == 10200


def test_order_history_includes_cancelled_orders(shop):
    ord_id = shop.orders.handle_create({
        "customer_id": "c1",
        "items": [{"sku": "BOOK", "quantity": 1}]
    }).body["order_id"]

    shop.orders.handle_cancel(ord_id)

    response = shop.insights.handle_order_history("c1")
    orders = response.body["orders"]
    assert len(orders) == 1
    assert orders[0]["order_id"] == ord_id
    assert orders[0]["status"] == "cancelled"

