"""Customer insight endpoints."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found


class CustomerInsightsController:
    def __init__(self, service: OrderService) -> None:
        self._service = service

    def handle_order_history(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        order_entries = []
        for order in reversed(orders):
            summary = self._service.summarize(order)
            order_entries.append({
                "order_id": order.order_id,
                "status": order.status,
                "total_cents": summary.total_cents,
            })

        return Response(200, {
            "customer_id": customer_id,
            "orders": order_entries,
        })

    def handle_lifetime_value(self, customer_id: str) -> Response:
        try:
            orders = self._service.list_for_customer(customer_id)
        except CustomerNotFound:
            return not_found("customer")

        active_orders = [o for o in orders if o.status != "cancelled"]
        lifetime_value = sum(
            self._service.summarize(o).total_cents for o in active_orders
        )

        return Response(200, {
            "customer_id": customer_id,
            "order_count": len(active_orders),
            "lifetime_value_cents": lifetime_value,
        })

    def handle_top_customers(self, limit: Any) -> Response:
        try:
            if type(limit) is not int or isinstance(limit, bool) or limit < 1:
                raise InvalidRequest("limit must be a positive integer")
        except InvalidRequest as exc:
            return bad_request(exc)

        customers = self._service.get_top_customers(limit)
        return Response(200, {
            "customers": [
                {
                    "customer_id": cid,
                    "name": name,
                    "lifetime_value_cents": value,
                }
                for cid, name, value in customers
            ]
        })

def cancel_order(self, order_id: str) -> Order:
    order = self.get_order(order_id)
    if order.status == "cancelled":
        raise Conflict(f"order {order_id} is already cancelled")
    for item in order.items:
        self._stock.set(item.sku, self._stock.get(item.sku) + item.quantity)
    return self._orders.set_status(order_id, "cancelled")

def get_top_customers(self, limit: int) -> list[tuple[str, str, int]]:
    """Return (customer_id, name, lifetime_value_cents) for top customers by lifetime value.

    Sorted by lifetime value (highest first), then by customer_id.
    Excludes customers with 0 lifetime value.
    """
    customers_with_value = []
    for customer in self._customers.list_all():
        orders = self._orders.list_for_customer(customer.customer_id)
        active_orders = [o for o in orders if o.status != "cancelled"]
        lifetime_value = sum(
            self.summarize(o).total_cents for o in active_orders
        )
        if lifetime_value > 0:
            customers_with_value.append((customer.customer_id, customer.name, lifetime_value))

    customers_with_value.sort(key=lambda x: (-x[2], x[0]))
    return customers_with_value[:limit]

